const rows = parseCsv(readFileSync(inputPath, 'utf8'));
const summary = buildSummary(rows);
const output = ['month,sales_total,mom_growth_rate', ...summary.map(row => [row.month, formatNumber(row.sales_total), row.mom_growth_rate === '' ? '' : row.mom_growth_rate.toFixed(6)].join(','))].join('\n') + '\n';
writeFileSync(outputPath, output);

